export class Counter {
  #n = 0;
  tick(): void { this.#n += 1; }
  get value(): number { return this.#n; }
}
// #n is private to the class — read it through value.
export function read(c: Counter): number { return c.#n; }

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { Counter, read } from '../src/counter.ts';
test('read reflects ticks', () => { const c = new Counter(); c.tick(); c.tick(); assert.equal(read(c), 2); });

